#!/usr/bin/env bash
# Starts `fermata-attest notary`. Settings (environment):
#   NOTARY_PRIVATE_KEY  32-byte hex signing key: yours, generated by you, never shared (required)
#   NOTARY_TOKEN        access token the gateway sends before each session (required: an open notary is anyone's)
#   PORT                listen port (default 7347)
#   DEMO_CA_URL         optional: the gateway's demo CA (https://<gateway>/ca.pem), only for its mock vendors
#   DEMO_CA_FILE        optional: the same CA from a file instead
# Real vendors are checked against Mozilla's roots, built into the binary.
set -euo pipefail
: "${NOTARY_PRIVATE_KEY:?set NOTARY_PRIVATE_KEY (generate one: openssl rand -hex 32)}"
: "${NOTARY_TOKEN:?set NOTARY_TOKEN (generate one: openssl rand -hex 24)}"
ARGS=(notary --listen "0.0.0.0:${PORT:-7347}" --roots mozilla)
if [ -n "${DEMO_CA_FILE:-}" ]; then
  ARGS+=(--ca "$DEMO_CA_FILE")
elif [ -n "${DEMO_CA_URL:-}" ]; then
  CA=$(mktemp)
  curl -fsS --max-time 20 "$DEMO_CA_URL" -o "$CA"
  ARGS+=(--ca "$CA")
fi
exec fermata-attest "${ARGS[@]}"
